package com.styleshop.product.controller;

import com.styleshop.product.model.Category; import com.styleshop.product.repository.CategoryRepository; import com.styleshop.product.service.ProductService; import com.styleshop.product.service.ProductService.ProductRequest; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController public class ProductController {private final ProductService service;private final CategoryRepository categories;private final Base64FileDecoder decoder;private final ProductCsvParser csvParser;private final ProductExcelParser excelParser;private final ProductPdfParser pdfParser;public ProductController(ProductService s,CategoryRepository c,Base64FileDecoder d,ProductCsvParser csv,ProductExcelParser excel,ProductPdfParser pdf){service=s;categories=c;decoder=d;csvParser=csv;excelParser=excel;pdfParser=pdf;}
 @GetMapping("/api/products") public Map<String,Object> search(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long categoryId,@RequestParam(required=false)BigDecimal minPrice,@RequestParam(required=false)BigDecimal maxPrice,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="9")int size,@RequestParam(defaultValue="id")String sortBy,@RequestParam(defaultValue="asc")String direction){if(!Set.of("id","name","price").contains(sortBy))sortBy="id";size=Math.max(1,Math.min(size,1000));var p=PageRequest.of(Math.max(page,0),size,Sort.by("desc".equalsIgnoreCase(direction)?Sort.Direction.DESC:Sort.Direction.ASC,sortBy));var r=service.search(keyword,categoryId,minPrice,maxPrice,p);Map<String,Object> out=new LinkedHashMap<>();out.put("content",r.getContent());out.put("page",r.getNumber());out.put("size",r.getSize());out.put("totalElements",r.getTotalElements());out.put("totalPages",r.getTotalPages());out.put("first",r.isFirst());out.put("last",r.isLast());out.put("dao",service.dao());return out;}
 @GetMapping("/api/products/{id}") public Object one(@PathVariable Long id){return service.one(id);}@GetMapping("/api/categories") public List<Category> categories(){return categories.findAll(Sort.by("id"));}
 @GetMapping("/api/admin/products") public Map<String,Object> admin(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long categoryId,@RequestParam(required=false)BigDecimal minPrice,@RequestParam(required=false)BigDecimal maxPrice,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="8")int size,@RequestParam(defaultValue="id")String sortBy,@RequestParam(defaultValue="asc")String direction){return search(keyword,categoryId,minPrice,maxPrice,page,size,sortBy,direction);}
 @PostMapping("/api/admin/products") public Object save(@RequestBody ProductRequest q){return service.save(q);}@DeleteMapping("/api/admin/products/{id}") public Map<String,String> delete(@PathVariable Long id){service.delete(id);return Map.of("message","商品已刪除");}
 @PostMapping("/api/admin/products/import/base64") public Object importBase64(@RequestBody Base64ImportRequest q){String name=q.fileName()==null?"":q.fileName().toLowerCase(Locale.ROOT);byte[] bytes=decoder.decode(q.base64());List<ProductRequest> parsed;if(name.endsWith(".csv"))parsed=csvParser.parse(bytes);else if(name.endsWith(".xlsx")||name.endsWith(".xls"))parsed=excelParser.parse(bytes);else if(name.endsWith(".pdf"))parsed=pdfParser.parse(bytes);else throw new IllegalArgumentException("只允許上傳 CSV、Excel (.xlsx/.xls) 或 PDF");return service.importProducts(parsed);}
 @PostMapping("/api/admin/categories") public Category add(@RequestBody Map<String,String> q){Category c=new Category();c.setName(q.get("name"));return categories.save(c);}@PutMapping("/api/admin/categories/{id}") public Category rename(@PathVariable Long id,@RequestBody Map<String,String> q){Category c=categories.findById(id).orElseThrow();c.setName(q.get("name"));return categories.save(c);}@DeleteMapping("/api/admin/categories/{id}") public Map<String,String> deleteCategory(@PathVariable Long id){categories.deleteById(id);return Map.of("message","種類已刪除");}
 public record Base64ImportRequest(String fileName,String base64){}
}
